const $=s=>document.querySelector(s);
const RAR=['Common','Uncommon','Rare','Epic','Showcase'],PRICE={Common:.1,Uncommon:.3,Rare:1.5,Epic:6,Showcase:15};
const OTHER=['Pokémon','Gundam','One Piece'];
let cards=[],byCode={},S;
const fresh=()=>({view:'pack',pk:3,opened:{},coins:100,own:{},slabs:[],nid:1,binders:[{id:'main',name:'Binder chính'}],bind:{},cur:'main',set:'all',rar:'all',page:0,sel:[],selm:false,miss:false});
const save=()=>{try{localStorage.setItem('rb_state',JSON.stringify(S))}catch(e){}};
function boot(list){cards=list.map(c=>({code:c.cardCode,name:c.fullName||c.name,set:c.setCode,setName:c.cardSet,rar:c.rarity,img:c.imageUrl,num:c.cardNumber}));
 try{localStorage.setItem('rb_cards',JSON.stringify(cards))}catch(e){}
 start()}
function start(){byCode={};cards.forEach(c=>byCode[c.code]=c);
 try{S=Object.assign(fresh(),JSON.parse(localStorage.getItem('rb_state')||'{}'))}catch(e){S=fresh()}
 S.sel=[];S.selm=false;$('#load').hidden=true;$('#app').hidden=false;
 buildPacks();render()}
function setList(){const m={};cards.forEach(c=>{(m[c.set]=m[c.set]||{code:c.set,name:c.setName,total:0}).total++});return Object.values(m)}
const price=(code,g)=>(PRICE[byCode[code].rar]||.1)*(g?(g>=10?8:4):1);
function tiles(){let t=[];
 if(S.cur==='main'){Object.keys(S.own).forEach(k=>S.own[k]>0&&t.push({key:'c:'+k,c:byCode[k],q:S.own[k]}));S.slabs.forEach(s=>t.push({key:'s:'+s.id,c:byCode[s.code],g:s.grade}))}
 else (S.bind[S.cur]||[]).forEach(k=>{const [ty,id]=[k.slice(0,1),k.slice(2)];if(ty==='c'&&S.own[id]>0)t.push({key:k,c:byCode[id],q:S.own[id]});if(ty==='s'){const s=S.slabs.find(x=>x.id==id);if(s)t.push({key:k,c:byCode[s.code],g:s.grade})}});
 if(S.set!=='all')t=t.filter(x=>x.c.set===S.set);
 if(S.rar!=='all')t=t.filter(x=>x.c.rar===S.rar);
 const ord=x=>RAR.indexOf(x.c.rar);
 t.sort((a,b)=>ord(b)-ord(a)||a.c.set.localeCompare(b.c.set)||a.c.num.localeCompare(b.c.num,undefined,{numeric:true}));
 if(S.miss&&S.cur==='main'){const have=new Set(t.map(x=>x.c.code));let all=cards.filter(c=>(S.set==='all'||c.set===S.set)&&(S.rar==='all'||c.rar===S.rar)&&!have.has(c.code));
  all.sort((a,b)=>a.set.localeCompare(b.set)||a.num.localeCompare(b.num,undefined,{numeric:true}));t=t.concat(all.map(c=>({key:'m:'+c.code,c,miss:1})))}
 return t}
function tileHTML(x){const sel=S.sel.includes(x.key);
 return `<button class="t ${x.miss?'miss':''} ${sel?'sel':''}" data-k="${x.key}" title="${x.c.name}"><img loading="lazy" src="${x.c.img}" alt="${x.c.name}" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'nm',textContent:this.alt}))">${x.g?`<span class="s">PSA ${x.g}</span>`:''}${x.q>1?`<span class="q">x${x.q}</span>`:''}</button>`}
function render(){
 $('#coins').textContent='$'+S.coins.toFixed(2);
 const owned=new Set([...Object.keys(S.own).filter(k=>S.own[k]>0),...S.slabs.map(s=>s.code)]);
 const sets=setList();
 $('#rings').innerHTML=`<button class="ring ${S.set==='all'?'on':''}" data-s="all"><i style="background:conic-gradient(var(--gold) ${owned.size/cards.length*100}%,#1c2640 0)"><b>${Math.round(owned.size/cards.length*100)}%</b></i>Tất cả</button>`+
 sets.map(s=>{const n=[...owned].filter(c=>byCode[c].set===s.code).length,p=Math.round(n/s.total*100);return `<button class="ring ${S.set===s.code?'on':''}" data-s="${s.code}" title="${n}/${s.total}"><i style="background:conic-gradient(var(--gold) ${p}%,#1c2640 0)"><b>${p}%</b></i>${s.name}</button>`}).join('');
 $('#rar').innerHTML=['all',...RAR].map(r=>`<button class="${S.rar===r?'on':''}" data-r="${r}">${r==='all'?'Tất cả độ hiếm':r}</button>`).join('');
 $('#miss').className=S.miss?'on':'';$('#selm').className=S.selm?'on':'';
 $('#tcgs').innerHTML=`<button class="tcg on"><span>Riftbound</span><small>${Object.values(S.own).reduce((a,b)=>a+b,0)+S.slabs.length} lá</small></button>`+OTHER.map(n=>`<button class="tcg" disabled style="opacity:.5"><span>${n}</span><small>0 lá</small></button>`).join('');
 $('#binders').innerHTML=S.binders.map(b=>`<button class="${S.cur===b.id?'on':''}" data-b="${b.id}">${b.name}</button>`).join('')+'<button id="nb">+ Binder mới</button>';
 const t=tiles(),pages=Math.max(1,Math.ceil(t.length/9));S.page=Math.min(S.page,pages-1);
 $('#grid').innerHTML=t.slice(S.page*9,S.page*9+9).map(tileHTML).join('')||'<p style="grid-column:1/4;text-align:center;color:var(--mu)">Chưa có lá nào. Hãy xé pack ở cột bên phải.</p>';
 $('#pginfo').textContent=`Trang ${S.page+1} / ${pages} · ${t.filter(x=>!x.miss).length} lá`;
 $('#selbar').hidden=!S.selm;$('#selinfo').textContent=`Đã chọn ${S.sel.length} lá`;const pv=S.view==='pack';$('#binderView').hidden=pv;$('#packView').hidden=!pv;$('#vp').className=pv?'on':'';$('#vb').className=pv?'':'on';if(pv)drawPacks();save()}
function pick(set){const pool=r=>{const a=cards.filter(c=>c.set===set&&c.rar===r);return a[Math.floor(Math.random()*a.length)]};
 const out=[];for(let i=0;i<10;i++){let r=i<6?'Common':i<9?'Uncommon':(()=>{const x=Math.random();return x<.7?'Rare':x<.92?'Epic':'Showcase'})();let c=pool(r)||pool('Common');out.push(c)}return out}
function grant(n){const set=PACKS[S.pk].code;if(S.coins<4*n){alert('Không đủ tiền. Hãy bán bớt thẻ.');return null}
 S.coins-=4*n;S.opened[set]=(S.opened[set]||0)+n;const got=[];
 for(let p=0;p<n;p++)pick(set).forEach((c,i)=>{if(i===9&&Math.random()<.06){const s={id:S.nid++,code:c.code,grade:Math.random()<.4?10:9};S.slabs.push(s);got.push({key:'s',c,g:s.grade})}else{S.own[c.code]=(S.own[c.code]||0)+1;got.push({key:'c',c,q:1})}});
 return got}
function rip(n){const got=grant(n);if(!got)return;if(n===1){render();return ripShow(got)}
 $('#pull').innerHTML=got.slice(-30).map(tileHTML).join('');$('#ov').classList.add('on');render()}
function sellKeys(keys){let sum=0;keys.forEach(k=>{const id=k.slice(2);if(k[0]==='c'&&S.own[id]>0){S.own[id]--;sum+=price(id)}if(k[0]==='s'){const i=S.slabs.findIndex(x=>x.id==id);if(i>=0){sum+=price(S.slabs[i].code,S.slabs[i].grade);S.slabs.splice(i,1)}}});
 S.coins+=sum;S.sel=[];return sum}
let PACKS=[];const LOGOS={"ogn": "data:image/webp;base64,", "rad": "data:image/webp;base64,", "sfd": "data:image/webp;base64,", "unl": "data:image/webp;base64,"};const PACKIMG='data:image/jpeg;base64,',LOGO='data:image/png;base64,';
const ORDER=['ogn','sfd','unl','ven','rad','ogs'],HUE={ogn:22,sfd:150,unl:275,ven:275,rad:45,ogs:200};
const CLIP='polygon('+Array.from({length:33},(_,i)=>`${i*100/32}% ${i%2?8:0}px`).join(',')+','+Array.from({length:33},(_,i)=>`${100-i*100/32}% calc(100% - ${i%2?0:8}px)`).join(',')+')';
function pkInner(p){const img=p.art?`<img class="pa" src="${p.img}" alt="">`:`<img class="pa" src="${p.img||''}" alt="" style="transform:scale(1.7);transform-origin:50% 28%" onerror="this.remove()">`;
 const ttl=p.logo?`<img class="lg" src="${p.logo}" alt="${p.name}">`:`<div class="ttl">${p.name}</div>`;
 return `<div class="pk" style="--h:${p.hue};clip-path:${CLIP}">${img}<div class="tt"></div><div class="bt"></div><div class="st"></div><div class="wr"></div><div class="fx"></div>${ttl}<div class="bp"><small>${p.name.toUpperCase()}</small><span>10 thẻ bài</span></div><div class="crimp t"></div><div class="crimp b"></div><div class="sheen"></div></div>`}
function packHTML(p,i){return `<button class="pkw" data-pi="${i}" aria-label="${p.name}">${pkInner(p)}</button>`}
function buildPacks(){const sets=setList().sort((a,b)=>ORDER.indexOf(a.code)-ORDER.indexOf(b.code));
 PACKS=sets.map(s=>{const pool=cards.filter(c=>c.set===s.code&&/744x1039/.test(c.img)&&/^\d+-\d+$/.test(c.num));const top=pool.find(c=>c.rar==='Epic')||pool.find(c=>c.rar==='Showcase')||pool[0];const v=s.code==='ven';
  return{code:s.code,name:s.name,total:s.total,hue:HUE[s.code]??275,img:v?PACKIMG:top&&top.img,logo:v?LOGO:(LOGOS[s.code]||''),art:v}});
 $('#car').innerHTML=PACKS.map(packHTML).join('');if(S.pk>=PACKS.length)S.pk=0}
function drawPacks(){const st=innerWidth<700?70:125;
 document.querySelectorAll('.pkw').forEach((el,i)=>{const d=i-S.pk,a=Math.abs(d);el.style.transform=`translateX(${d*st}px) translateZ(${-a*60}px) rotateY(${-d*8}deg) scale(${1-a*.1})`;el.style.zIndex=20-a;el.classList.toggle('act',d===0);el.style.opacity=a>3?0:1;el.style.pointerEvents=a>3?'none':'auto';el.style.filter=`brightness(${1-a*.22}) drop-shadow(0 14px 22px #000a)`});
 const p=PACKS[S.pk],own=new Set([...Object.keys(S.own).filter(k=>S.own[k]>0),...S.slabs.map(s=>s.code)]),n=[...own].filter(c=>byCode[c].set===p.code).length;
 $('#pname').textContent=p.name;$('#pmeta').textContent=`${p.total} lá · hoàn thành ${Math.round(n/p.total*100)}% (${n}/${p.total}) · đã xé ${S.opened[p.code]||0} pack · pack ${S.pk+1}/${PACKS.length}`}
document.addEventListener('keydown',e=>{if(S&&S.view==='pack'&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){S.pk=(S.pk+(e.key==='ArrowRight'?1:PACKS.length-1))%PACKS.length;render()}});
document.addEventListener('click',e=>{const el=e.target.closest('button,#ovx');if(!el)return;
 if(el.dataset.s){S.set=el.dataset.s;S.page=0;render()}
 else if(el.dataset.r){S.rar=el.dataset.r;S.page=0;render()}
 else if(el.dataset.b){S.cur=el.dataset.b;S.page=0;render()}
 else if(el.dataset.pi!==undefined){S.pk=+el.dataset.pi;render()}
 else if(el.dataset.k&&el.closest('#grid')){if(!S.selm||el.dataset.k[0]==='m')return;const k=el.dataset.k,i=S.sel.indexOf(k);i>=0?S.sel.splice(i,1):S.sel.push(k);render()}
 else switch(el.id){
  case'vp':S.view='pack';render();break;case'vb':S.view='binder';render();break;
  case'pkl':S.pk=(S.pk+PACKS.length-1)%PACKS.length;render();break;case'pkr':S.pk=(S.pk+1)%PACKS.length;render();break;
  case'pkview':S.view='binder';S.cur='main';S.set=PACKS[S.pk].code;S.page=0;render();break;
  case'miss':S.miss=!S.miss;S.page=0;render();break;
  case'selm':S.selm=!S.selm;S.sel=[];render();break;
  case'prev':S.page=Math.max(0,S.page-1);render();break;
  case'next':S.page++;render();break;
  case'rip1':rip(1);break;case'rip10':rip(10);break;case'ovx':$('#ov').classList.remove('on');break;
  case'nb':{const n=prompt('Tên binder mới:');if(n){const id='b'+S.nid++;S.binders.push({id,name:n});S.bind[id]=[];S.cur=id;render()}break}
  case'sellsel':{if(S.sel.length&&confirm(`Bán ${S.sel.length} lá (mỗi lá 1 bản)?`)){S.coins;sellKeys(S.sel);render()}break}
  case'tobind':{const bs=S.binders.filter(b=>b.id!=='main');if(!bs.length||!S.sel.length){alert('Hãy tạo binder mới và chọn thẻ trước.');break}
   const n=parseInt(prompt('Thêm vào binder số mấy?\n'+bs.map((b,i)=>`${i+1}. ${b.name}`).join('\n')),10);const b=bs[n-1];if(b){S.bind[b.id]=[...new Set([...(S.bind[b.id]||[]),...S.sel])];S.sel=[];render()}break}
  case'sdup':{const ks=Object.keys(S.own).filter(k=>S.own[k]>1).flatMap(k=>Array(S.own[k]-1).fill('c:'+k));if(ks.length&&confirm(`Bán ${ks.length} lá trùng (giữ lại 1 bản mỗi lá)?`)){sellKeys(ks);render()}break}
  case'scheap':{const ks=Object.keys(S.own).filter(k=>S.own[k]>0&&price(k)<.5).flatMap(k=>Array(S.own[k]).fill('c:'+k));if(ks.length&&confirm(`Bán ${ks.length} lá rẻ (dưới $0.50, bán hết cả bản)?`)){sellKeys(ks);render()}break}
  case'sslab':{const ks=S.slabs.map(s=>'s:'+s.id);if(ks.length&&confirm(`Bán ${ks.length} slab PSA?`)){sellKeys(ks);render()}break}
  case'reset':if(confirm('Xóa toàn bộ thẻ, binder và tiền đã lưu?')){localStorage.removeItem('rb_state');S=fresh();render()}break}});

/* ===== XÉ PACK TƯƠNG TÁC ===== */
const RC={Common:'#9aa5bd',Uncommon:'#7fd69a',Rare:'#5cb8ff',Epic:'#c06bff',Showcase:'#ffd24a'};
let R=null,cur=null;
function ripSnd(){try{const A=new (window.AudioContext||window.webkitAudioContext)(),n=A.sampleRate*.4,b=A.createBuffer(1,n,A.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,2)*(.6+.4*Math.sin(i/90));const s=A.createBufferSource();s.buffer=b;const f=A.createBiquadFilter();f.type='highpass';f.frequency.value=1800;const g=A.createGain();g.gain.value=.5;s.connect(f).connect(g).connect(A.destination);s.start()}catch(e){}}
function ripUI(){if(R)return;R=document.createElement('div');R.id='rip';R.className='rip';
 R.innerHTML=`<button class="rx" id="ripx" aria-label="Đóng">✕</button><div class="rstage"><div class="rglow"></div><div class="rpack" id="rpack" tabindex="0" role="button" aria-label="Vuốt ngang qua đầu pack để xé"><div class="half" id="rbody"></div><div class="rlight"></div><div class="half" id="rtop"></div><div class="rguide"><span>✂ Vuốt ngang để xé</span></div></div><div class="rdeck" id="rdeck"></div><div class="rflash" id="rflash"></div></div><p class="rhint" id="rhint"></p><div class="row"><button id="rskip" hidden>Lật hết</button></div>`;
 document.body.appendChild(R);
 const rp=$('#rpack'),top=$('#rtop'),body=$('#rbody');let x0=null,dir=1,pr=0;
 const setP=(p,d)=>{pr=p;rp.style.setProperty('--lt',p);R.style.setProperty('--gl',.25+p*.65);top.style.transformOrigin=d>0?'100% 13%':'0% 13%';top.style.transform=`translateY(${-p*14}px) rotate(${-d*p*8}deg)`;body.style.transform=`translateY(${p*5}px)`};
 const tear=d=>{if(!cur||cur.open)return;cur.open=true;rp.classList.add('open');ripSnd();navigator.vibrate&&navigator.vibrate(30);
  top.style.transformOrigin=d>0?'100% 13%':'0% 13%';top.style.transform=`translate(${d*60}px,-190px) rotate(${-d*32}deg)`;top.style.opacity=0;
  $('#rflash').classList.add('go');R.style.setProperty('--gl',1);$('#rhint').textContent='';
  setTimeout(()=>{body.style.transform='translateY(150px) scale(.92)';body.style.opacity=0;showDeck()},380);
  setTimeout(()=>{rp.style.display='none';R.style.setProperty('--gl',.25)},900)};
 rp.onpointerdown=e=>{if(!cur||cur.open)return;x0=e.clientX;rp.classList.add('drag');rp.setPointerCapture(e.pointerId)};
 rp.onpointermove=e=>{if(!cur||cur.open)return;const b=rp.getBoundingClientRect();
  if(x0===null){const px=(e.clientX-b.left)/b.width,py=(e.clientY-b.top)/b.height;rp.style.setProperty('--ry',(px-.5)*16+'deg');rp.style.setProperty('--rx',(.5-py)*12+'deg');rp.style.setProperty('--mx',px*100+'%');rp.style.setProperty('--my',py*100+'%');return}
  const dx=e.clientX-x0;dir=dx>=0?1:-1;const p=Math.min(1,Math.abs(dx)/(b.width*.75));setP(p,dir);if(p>=1){x0=null;rp.classList.remove('drag');tear(dir)}};
 rp.onpointerup=rp.onpointercancel=e=>{if(x0===null)return;const tap=Math.abs(e.clientX-x0)<6;x0=null;rp.classList.remove('drag');if(tap||pr>=.5)tear(tap?1:dir);else setP(0,dir)};
 rp.onpointerleave=()=>{if(x0===null){rp.style.setProperty('--rx','0deg');rp.style.setProperty('--ry','0deg')}};
 rp.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();tear(1)}};
 $('#ripx').onclick=()=>{cur&&!cur.done?finishRip():R.classList.remove('on')};
 $('#rskip').onclick=()=>finishRip();
 $('#rdeck').onclick=e=>{const c=e.target.closest('.rc');if(!c||!cur||+c.dataset.i!==cur.idx)return;step(c)}}
function hint(g){const n=cur.got.length;$('#rhint').textContent=g?`${g.c.name} · ${g.c.rar}${g.g?` · PSA ${g.g}`:''} — chạm để sang thẻ tiếp`:`Chạm để lật thẻ ${cur.idx+1}/${n}`}
function showDeck(){const dk=$('#rdeck');
 dk.innerHTML=cur.got.map((g,i)=>`<div class="rc" style="z-index:${20-i};--c:${RC[g.c.rar]||'#9aa5bd'};transform:translate(${(i%3-1)*2}px,${-i*1.5}px) rotate(${(i%5-2)*.9}deg)" data-i="${i}"><div class="in"><div class="rb">✦</div><div class="rf ${g.c.rar==='Showcase'||g.c.rar==='Epic'?'holo':''}"><img src="${g.c.img}" alt="${g.c.name}" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'nm',textContent:this.alt}))">${g.g?`<span class="s">PSA ${g.g}</span>`:''}</div></div></div>`).join('');
 dk.classList.add('on');$('#rskip').hidden=false;hint()}
function step(c){const g=cur.got[cur.idx];
 if(!c.classList.contains('flip')){c.classList.add('flip');if(RAR.indexOf(g.c.rar)>=2||g.g){c.classList.add('hi');R.style.setProperty('--h',{Rare:210,Epic:285,Showcase:48}[g.c.rar]||48);R.style.setProperty('--gl',.95);setTimeout(()=>R.style.setProperty('--gl',.25),800);navigator.vibrate&&navigator.vibrate(g.c.rar==='Showcase'?[40,40,80]:20)}hint(g)}
 else{c.classList.add('out');cur.idx++;if(cur.idx>=cur.got.length)setTimeout(finishRip,450);else hint()}}
function finishRip(){if(!cur)return;cur.done=true;R.classList.remove('on');$('#pull').innerHTML=cur.got.map(tileHTML).join('');$('#ov').classList.add('on');render();cur=null}
function ripShow(got){ripUI();const p=PACKS[S.pk],ty=13,J=Array.from({length:25},(_,i)=>`${(i*100/24).toFixed(2)}% ${(ty+Math.random()*2.6-1.3).toFixed(2)}%`);
 cur={got,idx:0,done:false,open:false};
 const rp=$('#rpack'),top=$('#rtop'),body=$('#rbody');
 top.innerHTML=pkInner(p);body.innerHTML=pkInner(p);
 top.style.clipPath=`polygon(0 0,100% 0,${[...J].reverse().join(',')})`;body.style.clipPath=`polygon(${J.join(',')},100% 100%,0 100%)`;
 [top,body].forEach(e=>{e.style.transform='';e.style.opacity=''});
 rp.className='rpack';rp.style.display='';rp.style.setProperty('--lt',0);
 $('#rdeck').classList.remove('on');$('#rdeck').innerHTML='';$('#rskip').hidden=true;
 const f=$('#rflash');f.classList.remove('go');void f.offsetWidth;
 R.style.setProperty('--h',p.hue);R.style.setProperty('--gl',.25);
 $('#rhint').textContent='Vuốt ngang qua đầu pack để xé (hoặc chạm một lần)';
 R.classList.add('on');rp.focus({preventScroll:true})}
/* nghiêng pack ở vòng xoay theo con trỏ */
document.addEventListener('pointermove',e=>{const el=e.target.closest&&e.target.closest('.pkw.act');if(!el)return;const b=el.getBoundingClientRect(),px=(e.clientX-b.left)/b.width,py=(e.clientY-b.top)/b.height,k=el.firstElementChild;k.style.setProperty('--ry',(px-.5)*18+'deg');k.style.setProperty('--rx',(.5-py)*14+'deg');k.style.setProperty('--mx',px*100+'%');k.style.setProperty('--my',py*100+'%')});
document.addEventListener('pointerout',e=>{const el=e.target.closest&&e.target.closest('.pkw');if(el){const k=el.firstElementChild;k.style.setProperty('--rx','0deg');k.style.setProperty('--ry','0deg')}});
$('#file').onchange=async e=>{try{boot(JSON.parse(await e.target.files[0].text()))}catch(x){alert('File không đọc được: '+x.message)}};
(async()=>{try{const c=JSON.parse(localStorage.getItem('rb_cards')||'null');if(c&&c.length){cards=c;return start()}}catch(e){}
 try{const r=await fetch('cards.json');if(r.ok)return boot(await r.json())}catch(e){}
 $('#load').hidden=false})();